<div class="page-heading"><div><span class="eyebrow">Competencia y participación</span><h1>Programa de capacitaciones</h1><p>Formación dirigida a los peligros prioritarios y a todos los niveles de la organización.</p></div><a href="#nueva-capacitacion" class="btn-primary"><?= icon('plus', 'h-4 w-4') ?> Programar capacitación</a></div>
<?php $total = count($trainings); $done = count(array_filter($trainings, fn($item) => $item['estado'] === 'Realizada')); $hours = array_sum(array_map(fn($item) => (float) $item['duracion_horas'], $trainings)); ?>
<section class="mt-6 grid grid-cols-3 gap-3"><div class="ios-card p-4"><p class="text-[11px] text-slate-400">Programadas / total</p><p class="mt-2 text-2xl font-semibold"><?= $total - $done ?> <span class="text-sm text-slate-400">/ <?= $total ?></span></p></div><div class="ios-card p-4"><p class="text-[11px] text-slate-400">Realizadas</p><p class="mt-2 text-2xl font-semibold text-emerald-600"><?= $done ?></p></div><div class="ios-card p-4"><p class="text-[11px] text-slate-400">Horas planificadas</p><p class="mt-2 text-2xl font-semibold"><?= e($hours) ?></p></div></section>
<section class="ios-card mt-6 overflow-hidden"><div class="card-heading"><div><h2>Cronograma de formación</h2><p>Gestiona participantes, asistencia, evaluación y eficacia en cada capacitación.</p></div></div><?php if ($trainings === []): ?><div class="empty-state"><span class="empty-icon"><?= icon('cap', 'h-7 w-7') ?></span><h3>No hay capacitaciones</h3><p>Programa la primera actividad de formación.</p></div><?php else: ?><div class="divide-y divide-slate-100"><?php foreach ($trainings as $training): ?><article class="grid gap-4 p-5 sm:grid-cols-[90px_1fr_auto] sm:p-6"><div class="date-tile !h-[68px] !w-[68px]<?= is_overdue($training) ? ' is-overdue' : '' ?>"><strong class="!text-xl"><?= date('d', strtotime($training['fecha_programada'])) ?></strong><span><?= ['ENE','FEB','MAR','ABR','MAY','JUN','JUL','AGO','SEP','OCT','NOV','DIC'][(int) date('n', strtotime($training['fecha_programada'])) - 1] ?></span></div><div><div class="flex flex-wrap items-center gap-2"><span class="badge badge-blue"><?= e($training['tipo_formacion']) ?></span><span class="badge badge-gray"><?= e($training['modalidad']) ?></span><span class="badge <?= status_class($training['estado']) ?>"><?= e($training['estado']) ?></span><?php if (is_overdue($training)): ?><span class="badge badge-red">Fecha vencida</span><?php endif; ?></div><h3 class="mt-2.5 text-sm font-semibold leading-5 text-slate-800"><?= e($training['tema']) ?></h3><p class="mt-1.5 max-w-3xl text-xs leading-5 text-slate-500"><?= e($training['descripcion']) ?></p><p class="mt-2 text-[11px] text-slate-400"><?= e($training['responsable']) ?> · <?= e($training['duracion_horas']) ?> horas · <?= format_date($training['fecha_programada'], true) ?></p></div><div class="min-w-[200px] sm:self-center"><div class="mb-3 flex flex-wrap gap-3"><a href="<?= e(url('/capacitaciones/' . $training['id'])) ?>" class="inline-flex items-center gap-1 text-[11px] font-medium text-blue-600 hover:underline"><?= icon('users', 'h-3.5 w-3.5') ?> Asistencia</a><a href="<?= e(url('/evidencias?vinculo=' . rawurlencode('capacitacion:' . $training['id']) . '#cargar')) ?>" class="inline-flex items-center gap-1 text-[11px] font-medium text-blue-600 hover:underline"><?= icon('upload', 'h-3.5 w-3.5') ?> Evidencias</a><a href="<?= e(url('/capacitaciones/' . $training['id'] . '/editar')) ?>" class="inline-flex items-center gap-1 text-[11px] font-medium text-blue-600 hover:underline"><?= icon('edit', 'h-3.5 w-3.5') ?> Editar</a><form method="post" action="<?= e(url('/capacitaciones/' . $training['id'] . '/eliminar')) ?>" data-confirm="¿Eliminar esta capacitación del cronograma? Conserva por separado cualquier evidencia de formación ya realizada."><?= csrf_field() ?><button type="submit" class="inline-flex items-center gap-1 text-[11px] font-medium text-rose-600 hover:underline"><?= icon('x', 'h-3.5 w-3.5') ?> Eliminar</button></form></div><form method="post" action="<?= e(url('/capacitaciones/' . $training['id'] . '/estado')) ?>" class="flex flex-wrap gap-2"><?= csrf_field() ?><input type="date" name="fecha_realizacion" class="input h-9 !w-auto flex-1 text-xs" value="<?= e($training['fecha_realizacion']) ?>" title="Fecha real de realización"><select name="estado" class="input h-9 !w-auto flex-1 text-xs"><?php foreach (['Programada','Realizada','Cancelada'] as $state): ?><option<?= selected($training['estado'], $state) ?>><?= $state ?></option><?php endforeach; ?></select><button class="btn-secondary h-9 px-3" type="submit">Guardar</button></form></div></article><?php endforeach; ?></div><?php endif; ?></section>
<section id="matriz-por-puesto" class="ios-card mt-6 p-5 sm:p-6"><div class="section-heading"><span class="section-icon"><?= icon('grid','h-5 w-5') ?></span><div><h2>Matriz de cobertura por puesto</h2><p>Cruza el directorio activo con formaciones y participantes reales. Los vacíos orientan la revisión de necesidades; no demuestran por sí solos un incumplimiento.</p></div></div><?php if($matrix===[]): ?><p class="mt-5 rounded-xl bg-slate-50 p-4 text-xs text-slate-400">No hay cargos en el directorio ni formaciones registradas.</p><?php endif; ?><div class="mt-5 space-y-4"><?php foreach($matrix as $position): ?><?php $enrollments=array_sum(array_column($position['formaciones'],'inscritos'));$attendance=array_sum(array_column($position['formaciones'],'asistencias'));$evaluations=array_sum(array_column($position['formaciones'],'evaluaciones'));$certificates=array_sum(array_column($position['formaciones'],'constancias')); ?><article class="rounded-2xl border border-slate-200 p-4"><div class="flex flex-wrap items-start justify-between gap-3"><div><h3 class="text-sm font-semibold text-slate-800"><?= e($position['cargo']) ?></h3><p class="mt-1 text-[11px] text-slate-400"><?= e($position['area']?:'Área no especificada') ?> · <?= (int)$position['trabajadores'] ?> personas activas en este cargo/área del directorio</p></div><span class="badge badge-gray"><?= count($position['formaciones']) ?> formaciones</span></div><div class="mt-3 grid grid-cols-2 gap-2 text-center sm:grid-cols-4"><div class="rounded-xl bg-slate-50 p-2"><strong class="block text-sm"><?= $enrollments ?></strong><span class="text-[10px] text-slate-400">Inscripciones</span></div><div class="rounded-xl bg-slate-50 p-2"><strong class="block text-sm"><?= $attendance ?></strong><span class="text-[10px] text-slate-400">Asistencias</span></div><div class="rounded-xl bg-slate-50 p-2"><strong class="block text-sm"><?= $evaluations ?></strong><span class="text-[10px] text-slate-400">Evaluaciones</span></div><div class="rounded-xl bg-slate-50 p-2"><strong class="block text-sm"><?= $certificates ?></strong><span class="text-[10px] text-slate-400">Constancias emitidas</span></div></div><?php if($position['formaciones']===[]): ?><p class="mt-3 text-xs text-amber-700">Sin formación registrada para este cargo. Revisa sus peligros, inducción y necesidades antes de programar.</p><?php else: ?><div class="mt-3 overflow-x-auto"><table class="data-table"><thead><tr><th>Formación</th><th>Estado</th><th>Destino / necesidad</th><th>Inscritos</th><th>Asistencias</th><th>Evaluaciones</th><th>Constancias</th></tr></thead><tbody><?php foreach($position['formaciones'] as $item): ?><tr><td><a href="<?= e(url('/capacitaciones/'.$item['id'])) ?>" class="font-medium text-blue-600 hover:underline"><?= e($item['tema']) ?></a><span class="block text-[10px] text-slate-400"><?= e($item['tipo_formacion']) ?> · <?= format_date($item['fecha_realizacion']?:$item['fecha_programada']) ?></span></td><td><span class="badge <?= status_class($item['estado']) ?>"><?= e($item['estado']) ?></span></td><td class="max-w-xs"><span class="block text-xs"><?= e($item['area_puesto']?:'Sin destino especificado') ?></span><span class="mt-1 block whitespace-pre-line text-[10px] text-slate-400"><?= e($item['necesidad_detectada']?:'Necesidad no especificada') ?></span></td><td><?= (int)$item['inscritos'] ?></td><td><?= (int)$item['asistencias'] ?></td><td><?= (int)$item['evaluaciones'] ?></td><td><?= (int)$item['constancias'] ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></article><?php endforeach; ?></div><p class="mt-4 text-[10px] leading-4 text-slate-400">Los totales suman participaciones en cada formación, no personas únicas. Una constancia acredita participación con los datos históricos emitidos; no certifica competencia automáticamente.</p></section>
<details id="nueva-capacitacion" class="ios-card mt-6 overflow-hidden"<?= $errors !== [] ? ' open' : '' ?>><summary class="cursor-pointer list-none p-5"><div class="section-heading"><span class="section-icon"><?= icon('cap', 'h-5 w-5') ?></span><div><h2>Programar nueva capacitación</h2><p>Define el tema, la población objetivo en la descripción y los recursos necesarios.</p></div></div></summary><form method="post" action="<?= e(url('/capacitaciones')) ?>" class="grid gap-5 border-t border-slate-100 p-5 sm:grid-cols-2"><?= csrf_field() ?><div class="sm:col-span-2"><label class="label">Tema *</label><input name="tema" class="input" value="<?= e(old('tema')) ?>" required><?= field_error('tema') ?></div><div class="sm:col-span-2"><label class="label">Descripción y población objetivo</label><textarea name="descripcion" class="input min-h-24"><?= e(old('descripcion')) ?></textarea></div><div><label class="label">Tipo de formación *</label><select name="tipo_formacion" class="input"><?php foreach($trainingTypes as $type): ?><option<?= selected(old('tipo_formacion','Capacitacion de seguridad'),$type) ?>><?= e($type) ?></option><?php endforeach; ?></select></div><div><label class="label">Área / puesto / proceso *</label><input name="area_puesto" class="input" required value="<?= e(old('area_puesto')) ?>"></div><div class="sm:col-span-2"><label class="label">Necesidad detectada / peligro / brecha *</label><textarea name="necesidad_detectada" class="input min-h-20" required><?= e(old('necesidad_detectada')) ?></textarea></div><div class="sm:col-span-2"><label class="label">Temas normativos y contenidos mínimos</label><textarea name="temas_normativos" class="input min-h-20"><?= e(old('temas_normativos')) ?></textarea></div><div><label class="label">Público objetivo</label><input name="publico_objetivo" class="input" value="<?= e(old('publico_objetivo')) ?>"></div><div><label class="label">Competencia</label><input name="competencia" class="input" value="<?= e(old('competencia')) ?>"></div><div class="sm:col-span-2"><label class="label">Contenido y metodología</label><textarea name="contenido" class="input min-h-20"><?= e(old('contenido')) ?></textarea></div><div class="sm:col-span-2"><label class="label">Idoneidad del instructor</label><input name="idoneidad_instructor" class="input" value="<?= e(old('idoneidad_instructor')) ?>"></div><div><label class="label">Responsable *</label><input name="responsable" class="input" value="<?= e(old('responsable')) ?>" required><?= field_error('responsable') ?></div><div><label class="label">Fecha programada *</label><input name="fecha_programada" type="date" class="input" value="<?= e(old('fecha_programada', date('Y-m-d', strtotime('+30 days')))) ?>" required></div><div><label class="label">Duración en horas *</label><input name="duracion_horas" type="number" min="0.5" step="0.5" class="input" value="<?= e(old('duracion_horas', 1)) ?>" required></div><div><label class="label">Modalidad *</label><select name="modalidad" class="input"><?php foreach (['Presencial','Virtual','Mixta'] as $mode): ?><option<?= selected(old('modalidad'), $mode) ?>><?= $mode ?></option><?php endforeach; ?></select></div><div class="sm:col-span-2 flex justify-end"><button class="btn-primary" type="submit">Programar capacitación</button></div></form></details>
<div class="mt-5 rounded-2xl bg-violet-50 p-4 text-[11px] leading-5 text-violet-800 ring-1 ring-violet-100"><strong>Evidencias recomendadas:</strong> programa, contenido, lista de asistencia, material utilizado, evaluación de aprendizaje cuando aplique y registro de eficacia. No uses el cambio de estado como único soporte.</div>
